<section class="card"><h2>Staff activity trail</h2><p class="muted">Attributed HR decisions · UTC · Sensitive salary values and account numbers are excluded.</p><?php foreach($snapshot['history'] as $event):?><div class="hr-event"><h3><?=access_h(str_replace(['hr.','_'],['',' '],$event['action'] ?? 'HR event'))?></h3><p>Actor #<?=(int)($event['actor_id'] ?? $event['created_by'] ?? 0)?> · <?=access_h(display_date($event['created_at'] ?? $event['occurred_at'] ?? ''))?> UTC</p><?php if(!empty($event['reason_html'])):?><div><?=\Tivoli\Domain\Hr\HrRichText::sanitize($event['reason_html'])?></div><?php endif?></div><?php endforeach?><?php if(!$snapshot['history']):?><p>No HR events yet.</p><?php endif?></section>
